mapper.select:
SELECT * FROM (
    SELECT id, year, equip_name, sensor_type, zone_name, change_date, next_change_date, remark,
           reg_user_name, use_yn, reg_dt, upd_dt,
           LAG(change_date) OVER (PARTITION BY equip_name, zone_name, sensor_type ORDER BY year) AS prev_change_date
    FROM condition_sensor
    WHERE use_yn = 'Y'
) t
WHERE t.year = #{year}

    AND t.sensor_type = #{sensorType}

ORDER BY t.sensor_type ASC, t.equip_name ASC, t.id ASC
